-- BASELINE for a FRESH InsForge TEST project: the DevBook application schema as it is in production today (before 01-04).
-- Generated by make-baseline.mjs from sandbox/schema.sql. NOT applied anywhere. Load into the TEST project only.
-- Exact in production export: users, books, phases, steps, book_members, attachments (columns), all functions, triggers, indexes, policies.
-- RECONSTRUCTED (parity gap, see README): book_access, user_followers, step_progress, book_progress, book_revisions columns;
-- enum values of book_difficulty and step_type are assumed. book_invitations is not reproduced. Roles, auth.users, auth.uid() and
-- default privileges come from the platform; nothing here creates them.
BEGIN;

CREATE TYPE access_level AS ENUM ('PUBLIC', 'UNLISTED', 'PRIVATE', 'FOLLOWERS_ONLY', 'SELECTED_USERS');
CREATE TYPE publication_status AS ENUM ('DRAFT', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE book_role AS ENUM ('OWNER', 'EDITOR', 'REVIEWER', 'VIEWER');
CREATE TYPE book_difficulty AS ENUM ('BEGINNER', 'INTERMEDIATE', 'ADVANCED');
CREATE TYPE step_type AS ENUM ('MARKDOWN');

CREATE TABLE users (id uuid NOT NULL, name text, avatar_url text, bio text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT users_pkey PRIMARY KEY (id), CONSTRAINT users_id_fkey FOREIGN KEY (id) REFERENCES auth.users (id) ON DELETE CASCADE);

CREATE TABLE books (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, slug text NOT NULL, description text, cover_url text, publication_status publication_status NOT NULL DEFAULT 'DRAFT'::publication_status, access_level access_level NOT NULL DEFAULT 'PRIVATE'::access_level, estimated_read_time integer DEFAULT 0, difficulty book_difficulty DEFAULT 'BEGINNER'::book_difficulty, language text DEFAULT 'en'::text, tags text[] DEFAULT '{}'::text[], version text DEFAULT '1.0.0'::text, published_at timestamptz, revision integer NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, search_vector tsvector, CONSTRAINT books_pkey PRIMARY KEY (id), CONSTRAINT books_created_by_fkey FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL, CONSTRAINT books_deleted_by_fkey FOREIGN KEY (deleted_by) REFERENCES users (id) ON DELETE SET NULL, CONSTRAINT books_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL);
CREATE UNIQUE INDEX books_slug_lower_idx ON public.books USING btree (lower(slug)) WHERE (deleted_at IS NULL);

CREATE TABLE phases (id uuid NOT NULL DEFAULT gen_random_uuid(), book_id uuid NOT NULL, title text NOT NULL, position integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, CONSTRAINT phases_pkey PRIMARY KEY (id), CONSTRAINT phases_book_id_fkey FOREIGN KEY (book_id) REFERENCES books (id) ON DELETE CASCADE);
CREATE UNIQUE INDEX unique_book_phase_position ON public.phases USING btree (book_id, "position");

CREATE TABLE steps (id uuid NOT NULL DEFAULT gen_random_uuid(), phase_id uuid NOT NULL, title text NOT NULL, type step_type NOT NULL DEFAULT 'MARKDOWN'::step_type, content jsonb DEFAULT '{}'::jsonb, position integer NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, search_vector tsvector, CONSTRAINT steps_pkey PRIMARY KEY (id), CONSTRAINT steps_phase_id_fkey FOREIGN KEY (phase_id) REFERENCES phases (id) ON DELETE CASCADE);
CREATE UNIQUE INDEX unique_phase_step_position ON public.steps USING btree (phase_id, "position");
CREATE INDEX idx_steps_search ON public.steps USING gin (search_vector);

CREATE TABLE book_members (book_id uuid NOT NULL, user_id uuid NOT NULL, role book_role NOT NULL DEFAULT 'VIEWER'::book_role, joined_at timestamptz DEFAULT now(), invited_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT book_members_pkey PRIMARY KEY (book_id, user_id), CONSTRAINT book_members_book_id_fkey FOREIGN KEY (book_id) REFERENCES books (id) ON DELETE CASCADE, CONSTRAINT book_members_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE);

CREATE TABLE attachments (id uuid NOT NULL DEFAULT gen_random_uuid(), step_id uuid NOT NULL, file_name text NOT NULL, storage_path text NOT NULL, file_type text NOT NULL, file_size integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, CONSTRAINT attachments_pkey PRIMARY KEY (id), CONSTRAINT attachments_step_id_fkey FOREIGN KEY (step_id) REFERENCES steps (id) ON DELETE CASCADE);

-- reconstructed
CREATE TABLE book_access (book_id uuid NOT NULL, user_id uuid NOT NULL, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (book_id, user_id), FOREIGN KEY (book_id) REFERENCES books (id) ON DELETE CASCADE);
CREATE TABLE user_followers (follower_id uuid NOT NULL, following_id uuid NOT NULL, PRIMARY KEY (follower_id, following_id));
CREATE TABLE step_progress (user_id uuid NOT NULL, step_id uuid NOT NULL, status text, PRIMARY KEY (user_id, step_id), FOREIGN KEY (step_id) REFERENCES steps (id) ON DELETE CASCADE);
CREATE TABLE book_progress (user_id uuid NOT NULL, book_id uuid NOT NULL, progress_percentage integer DEFAULT 0, last_read_step_id uuid, PRIMARY KEY (user_id, book_id), FOREIGN KEY (book_id) REFERENCES books (id) ON DELETE CASCADE);
CREATE TABLE book_revisions (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, book_id uuid NOT NULL REFERENCES books (id) ON DELETE CASCADE, revision integer NOT NULL, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (book_id, revision));

-- ===== functions, verbatim from `db functions --json` =====
CREATE OR REPLACE FUNCTION public.can_delete_book(target_book_id uuid, req_user_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $function$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM book_members
        WHERE book_id = target_book_id AND user_id = req_user_id AND role = 'OWNER'
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.can_edit_book(target_book_id uuid, req_user_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $function$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM book_members
        WHERE book_id = target_book_id AND user_id = req_user_id AND role IN ('OWNER', 'EDITOR')
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.can_manage_members(target_book_id uuid, req_user_id uuid) RETURNS boolean LANGUAGE plpgsql SET search_path TO 'public', 'pg_temp' AS $function$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM book_members
        WHERE book_id = target_book_id AND user_id = req_user_id AND role = 'OWNER'
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.can_read_book(target_book_id uuid, req_user_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $function$
DECLARE
    book_access_level access_level;
    owner_id UUID;
BEGIN
    IF EXISTS (SELECT 1 FROM books WHERE id = target_book_id AND deleted_at IS NOT NULL) THEN
        RETURN EXISTS (SELECT 1 FROM book_members WHERE book_id = target_book_id AND user_id = req_user_id AND role = 'OWNER');
    END IF;

    SELECT access_level INTO book_access_level FROM books WHERE id = target_book_id;

    IF book_access_level = 'PUBLIC' OR book_access_level = 'UNLISTED' THEN
        RETURN TRUE;
    END IF;

    IF EXISTS (SELECT 1 FROM book_members WHERE book_id = target_book_id AND user_id = req_user_id) THEN
        RETURN TRUE;
    END IF;

    IF book_access_level = 'FOLLOWERS_ONLY' THEN
        SELECT user_id INTO owner_id FROM book_members WHERE book_id = target_book_id AND role = 'OWNER' LIMIT 1;
        IF EXISTS (SELECT 1 FROM user_followers WHERE follower_id = req_user_id AND following_id = owner_id) THEN
            RETURN TRUE;
        END IF;
    END IF;

    IF book_access_level = 'SELECTED_USERS' THEN
        IF EXISTS (SELECT 1 FROM book_access WHERE book_id = target_book_id AND user_id = req_user_id) THEN
            RETURN TRUE;
        END IF;
    END IF;

    RETURN FALSE;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fill_books_search_vector() RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN
    NEW.search_vector :=
        to_tsvector('english', coalesce(NEW.title, '')) ||
        to_tsvector('english', coalesce(NEW.description, ''));
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fill_steps_search_vector() RETURNS trigger LANGUAGE plpgsql AS $function$
BEGIN
    NEW.search_vector :=
        to_tsvector('english', coalesce(NEW.title, '')) ||
        to_tsvector('english', coalesce(NEW.content->>'markdown', ''));
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_book_id_for_phase(target_phase_id uuid) RETURNS uuid LANGUAGE plpgsql SET search_path TO 'public', 'pg_temp' AS $function$
BEGIN
    RETURN (SELECT book_id FROM phases WHERE id = target_phase_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_book_id_for_step(target_step_id uuid) RETURNS uuid LANGUAGE plpgsql SET search_path TO 'public', 'pg_temp' AS $function$
BEGIN
    RETURN (
        SELECT p.book_id 
        FROM phases p 
        JOIN steps s ON s.phase_id = p.id 
        WHERE s.id = target_step_id
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.trigger_add_book_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $function$
BEGIN
    INSERT INTO public.book_members (book_id, user_id, role)
    VALUES (NEW.id, NEW.created_by, 'OWNER');
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trigger_audit_metadata() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.created_by := coalesce(NEW.created_by, auth.uid());
        NEW.updated_by := coalesce(NEW.updated_by, auth.uid());
        NEW.created_at := coalesce(NEW.created_at, now());
        NEW.updated_at := coalesce(NEW.updated_at, now());
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.created_by := OLD.created_by; -- Preserve original creator
        NEW.updated_by := auth.uid();
        NEW.updated_at := now();
    END IF;
    RETURN NEW;
END;
$function$;

-- ===== triggers, from `db triggers --json` (the ones on the tables above) =====
CREATE TRIGGER trigger_attachments_audit BEFORE INSERT OR UPDATE ON attachments FOR EACH ROW EXECUTE FUNCTION trigger_audit_metadata();
CREATE TRIGGER trigger_books_audit BEFORE INSERT OR UPDATE ON books FOR EACH ROW EXECUTE FUNCTION trigger_audit_metadata();
CREATE TRIGGER trigger_books_owner AFTER INSERT ON books FOR EACH ROW EXECUTE FUNCTION trigger_add_book_owner();
CREATE TRIGGER trigger_books_search_update BEFORE INSERT OR UPDATE ON books FOR EACH ROW EXECUTE FUNCTION fill_books_search_vector();
CREATE TRIGGER trigger_phases_audit BEFORE INSERT OR UPDATE ON phases FOR EACH ROW EXECUTE FUNCTION trigger_audit_metadata();
CREATE TRIGGER trigger_steps_audit BEFORE INSERT OR UPDATE ON steps FOR EACH ROW EXECUTE FUNCTION trigger_audit_metadata();
CREATE TRIGGER trigger_steps_search_update BEFORE INSERT OR UPDATE ON steps FOR EACH ROW EXECUTE FUNCTION fill_steps_search_vector();

-- ===== RLS + policies, verbatim from `db policies --json` =====
ALTER TABLE attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE book_access ENABLE ROW LEVEL SECURITY;
ALTER TABLE book_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE book_progress ENABLE ROW LEVEL SECURITY;
ALTER TABLE book_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE books ENABLE ROW LEVEL SECURITY;
ALTER TABLE phases ENABLE ROW LEVEL SECURITY;
ALTER TABLE step_progress ENABLE ROW LEVEL SECURITY;
ALTER TABLE steps ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_followers ENABLE ROW LEVEL SECURITY;
ALTER TABLE users ENABLE ROW LEVEL SECURITY;

CREATE POLICY modify_attachments ON attachments FOR ALL TO public USING (can_edit_book(get_book_id_for_step(step_id), ( SELECT auth.uid() AS uid)));
CREATE POLICY select_attachments ON attachments FOR SELECT TO public USING (can_read_book(get_book_id_for_step(step_id), ( SELECT auth.uid() AS uid)));
CREATE POLICY modify_access ON book_access FOR ALL TO public USING (can_edit_book(book_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY select_access ON book_access FOR SELECT TO public USING (can_read_book(book_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY modify_members ON book_members FOR ALL TO public USING (can_manage_members(book_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY select_members ON book_members FOR SELECT TO public USING (can_read_book(book_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY modify_book_progress ON book_progress FOR ALL TO public USING (((user_id = ( SELECT auth.uid() AS uid)) AND can_read_book(book_id, ( SELECT auth.uid() AS uid))));
CREATE POLICY select_book_progress ON book_progress FOR SELECT TO public USING (((user_id = ( SELECT auth.uid() AS uid)) AND can_read_book(book_id, ( SELECT auth.uid() AS uid))));
CREATE POLICY modify_revisions ON book_revisions FOR ALL TO public USING (can_edit_book(book_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY select_revisions ON book_revisions FOR SELECT TO public USING (can_read_book(book_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY delete_books ON books FOR DELETE TO public USING (can_delete_book(id, ( SELECT auth.uid() AS uid)));
CREATE POLICY insert_books ON books FOR INSERT TO public WITH CHECK ((( SELECT auth.uid() AS uid) IS NOT NULL));
CREATE POLICY select_books ON books FOR SELECT TO public USING ((can_read_book(id, ( SELECT auth.uid() AS uid)) OR (created_by = ( SELECT auth.uid() AS uid))));
CREATE POLICY update_books ON books FOR UPDATE TO public USING (can_edit_book(id, ( SELECT auth.uid() AS uid)));
CREATE POLICY modify_phases ON phases FOR ALL TO public USING (can_edit_book(book_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY select_phases ON phases FOR SELECT TO public USING (can_read_book(book_id, ( SELECT auth.uid() AS uid)));
CREATE POLICY modify_step_progress ON step_progress FOR ALL TO public USING (((user_id = ( SELECT auth.uid() AS uid)) AND can_read_book(get_book_id_for_step(step_id), ( SELECT auth.uid() AS uid))));
CREATE POLICY select_step_progress ON step_progress FOR SELECT TO public USING (((user_id = ( SELECT auth.uid() AS uid)) AND can_read_book(get_book_id_for_step(step_id), ( SELECT auth.uid() AS uid))));
CREATE POLICY modify_steps ON steps FOR ALL TO public USING (can_edit_book(get_book_id_for_phase(phase_id), ( SELECT auth.uid() AS uid)));
CREATE POLICY select_steps ON steps FOR SELECT TO public USING (can_read_book(get_book_id_for_phase(phase_id), ( SELECT auth.uid() AS uid)));
CREATE POLICY modify_followers ON user_followers FOR ALL TO public USING ((follower_id = ( SELECT auth.uid() AS uid)));
CREATE POLICY select_followers ON user_followers FOR SELECT TO public USING (true);
CREATE POLICY modify_users ON users FOR ALL TO public USING ((id = ( SELECT auth.uid() AS uid)));
CREATE POLICY select_users ON users FOR SELECT TO public USING (((id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM books
  WHERE ((books.created_by = users.id) AND (books.deleted_at IS NULL) AND (books.access_level = 'PUBLIC'::access_level)))) OR (EXISTS ( SELECT 1
   FROM user_followers
  WHERE (((user_followers.follower_id = ( SELECT auth.uid() AS uid)) AND (user_followers.following_id = users.id)) OR ((user_followers.following_id = ( SELECT auth.uid() AS uid)) AND (user_followers.follower_id = users.id)))))));

COMMIT;
